-- Generated by Supabase CLI 2.121.0; additive repair of the unreleased M1 candidate.
-- Progress and evidence commit together. No source bytes, inference, or operational-row changes.
create table public.media_evidence_ingestion (
 actor_id uuid not null references public.actors(id) on delete cascade,
 source_chat_id uuid not null references public.chats(id) on delete cascade,
 attachment_id uuid not null,
 kind text not null check(kind in ('discovery','extracted','analysis','timing')),
 version text not null check(length(version) between 1 and 512),
 content_hash text not null check(length(content_hash) between 1 and 128),
 total_characters integer not null check(total_characters>0),
 next_offset integer not null default 0 check(next_offset>=0 and next_offset<=total_characters),
 updated_at timestamptz not null default clock_timestamp(),
 primary key(source_chat_id,attachment_id,kind,version)
);
alter table public.media_evidence_ingestion enable row level security;
revoke all on public.media_evidence_ingestion from public,anon,authenticated;
grant all on public.media_evidence_ingestion to service_role;
create trigger media_evidence_ingestion_owner before insert or update on public.media_evidence_ingestion
 for each row execute function public.media_evidence_owner_guard();

create function public.begin_media_evidence_ingestion(p_actor uuid,p_chat uuid,p_attachment uuid,p_kind text,p_version text,p_hash text,p_total integer)
returns integer language plpgsql security invoker set search_path=public,pg_temp as $$
declare progress public.media_evidence_ingestion;
begin
 perform 1 from public.chats where id=p_chat and actor_id=p_actor for share;
 if not found then raise exception 'Live source owner required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_chat::text||p_attachment::text||p_kind||p_version,0));
 insert into public.media_evidence_ingestion(actor_id,source_chat_id,attachment_id,kind,version,content_hash,total_characters)
 values(p_actor,p_chat,p_attachment,p_kind,p_version,p_hash,p_total) on conflict do nothing;
 select * into strict progress from public.media_evidence_ingestion
 where source_chat_id=p_chat and attachment_id=p_attachment and kind=p_kind and version=p_version;
 if progress.actor_id<>p_actor or progress.content_hash<>p_hash or progress.total_characters<>p_total then
  raise exception 'Evidence version does not match canonical content';
 end if;
 return progress.next_offset;
end $$;
revoke all on function public.begin_media_evidence_ingestion(uuid,uuid,uuid,text,text,text,integer) from public,anon,authenticated;
grant execute on function public.begin_media_evidence_ingestion(uuid,uuid,uuid,text,text,text,integer) to service_role;

create function public.append_media_evidence_batch(p_actor uuid,p_chat uuid,p_attachment uuid,p_kind text,p_version text,p_filename text,p_mime text,p_coverage text,p_created timestamptz,p_original boolean,p_hash text,p_total integer,p_offset integer,p_text text)
returns integer language plpgsql security invoker set search_path=public,pg_temp as $$
declare position integer; following integer;
begin
 if p_text is null or length(p_text)>230800 or p_offset is null or p_offset<0 or p_offset>=p_total or p_offset%3600<>0
  or length(p_text)<>least(230800,p_total-p_offset) or p_filename is null or length(p_filename)>255
  or p_mime is null or length(p_mime)>128 or p_coverage is null or length(p_coverage)>512 then
  raise exception 'Invalid bounded evidence batch';
 end if;
 position:=public.begin_media_evidence_ingestion(p_actor,p_chat,p_attachment,p_kind,p_version,p_hash,p_total);
 if p_offset<position then return position; end if; -- Same immutable version, already committed retry.
 if p_offset<>position then raise exception 'Evidence batches must be contiguous'; end if;
 following:=least(p_total::bigint,p_offset::bigint+230400)::integer;
 insert into public.media_evidence(actor_id,source_chat_id,attachment_id,kind,version,filename,mime_type,coverage,created_at,original_available,chunk_index,start_offset,body)
 select p_actor,p_chat,p_attachment,p_kind,p_version,p_filename,p_mime,p_coverage,p_created,p_original,(p_offset+n)/3600,p_offset+n,substring(p_text from n+1 for 4000)
 from generate_series(0,least(230399,p_total-p_offset-1),3600) n;
 update public.media_evidence_ingestion set next_offset=following,updated_at=clock_timestamp()
 where source_chat_id=p_chat and attachment_id=p_attachment and kind=p_kind and version=p_version;
 return following;
end $$;
revoke all on function public.append_media_evidence_batch(uuid,uuid,uuid,text,text,text,text,text,timestamptz,boolean,text,integer,integer,text) from public,anon,authenticated;
grant execute on function public.append_media_evidence_batch(uuid,uuid,uuid,text,text,text,text,text,timestamptz,boolean,text,integer,integer,text) to service_role;

-- Video canonical text already lives in PostgreSQL. Process one bounded page, even after delivery.
create function public.advance_media_video_evidence(p_actor uuid,p_chat uuid,p_attachment uuid,p_kind text,p_version text,p_filename text,p_mime text,p_coverage text,p_created timestamptz,p_original boolean,p_text text)
returns void language plpgsql security invoker set search_path=public,pg_temp as $$
declare total integer:=length(p_text); position integer; digest text:=md5(p_text);
begin
 if total<=230800 then
  perform public.save_media_evidence(p_actor,p_chat,p_attachment,p_kind,p_version,p_filename,p_mime,p_coverage,p_created,p_original,p_text);
 else
  position:=public.begin_media_evidence_ingestion(p_actor,p_chat,p_attachment,p_kind,p_version,digest,total);
  if position<total then
   perform public.append_media_evidence_batch(p_actor,p_chat,p_attachment,p_kind,p_version,p_filename,p_mime,p_coverage,p_created,p_original,digest,total,position,substring(p_text from position+1 for 230800));
  end if;
 end if;
end $$;
revoke all on function public.advance_media_video_evidence(uuid,uuid,uuid,text,text,text,text,text,timestamptz,boolean,text) from public,anon,authenticated;
grant execute on function public.advance_media_video_evidence(uuid,uuid,uuid,text,text,text,text,text,timestamptz,boolean,text) to service_role;

create or replace function public.reconcile_media_video(p_actor uuid,p_current_chat uuid) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare j record; f record; total integer:=0;
begin
 perform 1 from public.chats where id=p_current_chat and actor_id=p_actor for share;
 if not found then raise exception 'Live request owner required'; end if;
 for j in select v.* from public.video_analysis_jobs v
 join public.chats c on c.id=v.chat_id and c.actor_id=p_actor
 where v.actor_id=p_actor and v.attachment_path ~ ('^chats/'||v.chat_id::text||'/[0-9a-f-]{36}\.source$')
 and exists(select 1 from public.media_evidence e where e.source_chat_id=v.chat_id and e.attachment_id=split_part(split_part(v.attachment_path,'/',3),'.',1)::uuid)
 and ((v.status='completed' and length(v.analysis_text)>=25 and v.analysis_text !~* '^(I (cannot|can.t|am unable)|sorry|as an AI)' and not exists(select 1 from public.media_evidence e where not exists(select 1 from public.media_evidence_ingestion i where i.source_chat_id=e.source_chat_id and i.attachment_id=e.attachment_id and i.kind=e.kind and i.version=e.version and i.next_offset<i.total_characters) and e.version='job:'||v.id||':'||v.model||':'||md5(v.analysis_text)))
 or (v.fallback_state='completed' and length(v.fallback_text)>=25 and v.fallback_text !~* '^(I (cannot|can.t|am unable)|sorry|as an AI)' and not exists(select 1 from public.media_evidence e where not exists(select 1 from public.media_evidence_ingestion i where i.source_chat_id=e.source_chat_id and i.attachment_id=e.attachment_id and i.kind=e.kind and i.version=e.version and i.next_offset<i.total_characters) and e.version='job:'||v.id||':'||coalesce(v.fallback_model,'unknown-model')||':'||md5(v.fallback_text))))
 order by coalesce((select max(i.updated_at) from public.media_evidence_ingestion i where i.source_chat_id=v.chat_id and i.version like 'job:'||v.id||':%'),v.submitted_at),v.id limit 3
 loop
 select * into f from public.media_evidence e where e.source_chat_id=j.chat_id and e.attachment_id=split_part(split_part(j.attachment_path,'/',3),'.',1)::uuid limit 1;
 if j.status='completed' and length(j.analysis_text)>=25 and j.analysis_text !~* '^(I (cannot|can.t|am unable)|sorry|as an AI)' then
 perform public.advance_media_video_evidence(p_actor,j.chat_id,f.attachment_id,'analysis','job:'||j.id||':'||j.model||':'||md5(j.analysis_text),f.filename,f.mime_type,'model report; original-video coverage unknown',f.created_at,f.original_available,j.analysis_text);
 end if;
 if j.fallback_state='completed' and length(j.fallback_text)>=25 and j.fallback_text !~* '^(I (cannot|can.t|am unable)|sorry|as an AI)' then
 perform public.advance_media_video_evidence(p_actor,j.chat_id,f.attachment_id,'analysis','job:'||j.id||':'||coalesce(j.fallback_model,'unknown-model')||':'||md5(j.fallback_text),f.filename,f.mime_type,'sampled frames; supplied Qwen report; not independent confirmation',f.created_at,f.original_available,j.fallback_text);
 end if;
 total:=total+1;
 end loop;
 return total;
end $$;

create or replace function public.read_media_evidence(p_actor uuid,p_current_chat uuid,p_source_chat uuid,p_attachment uuid,p_kind text,p_version text,p_offset integer)
returns setof public.media_evidence language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if p_offset<0 or length(p_version)>512 then raise exception 'Invalid evidence location'; end if;
 perform 1 from public.chats where id=p_current_chat and actor_id=p_actor for share;
 if not found then raise exception 'Live request owner required'; end if;
 return query select e.* from public.media_evidence e join public.chats c on c.id=e.source_chat_id and c.actor_id=p_actor
 where e.actor_id=p_actor and e.source_chat_id=p_source_chat and e.attachment_id=p_attachment and e.kind=p_kind and e.version=p_version and e.start_offset::bigint+length(e.body)>p_offset
 order by e.start_offset limit 4;
end $$;
revoke all on function public.read_media_evidence(uuid,uuid,uuid,uuid,text,text,integer) from public,anon,authenticated;
grant execute on function public.read_media_evidence(uuid,uuid,uuid,uuid,text,text,integer) to service_role;
